    'en': {
      // --- Routing ---
      'routing_details': 'Route Details',
      'routing_solutions': 'solutions',
      'routing_tab_overview': 'Overview',
      'routing_tab_segments': 'Segments',
      'routing_tab_stops': 'Stops',
      'routing_trains_used': 'Trains used',
